using System.Windows;
using System.Windows.Controls;
using pk3DS.Core.NX;
using ThreeDS.Progressive;
using ThreeDS.Progressive.Models;
using ThreeDS.Progressive.Services.Switch;
internal static class SwitchPolishChecks
{
    private const string Team="bin/trainer/trainer_poke/trainer_poke_001.bin";
    private static void U16(byte[] b,int at,int v)=>BinaryPrimitives.WriteUInt16LittleEndian(b.AsSpan(at),(ushort)v);
    private static Dictionary<string,byte[]> LowLevel()
    {
        var source=SwitchParityChecks.Inputs();U16(source[Team],10,3);var learn=source[SwordShieldDataEditor.LearnPath];for(int e=1;e<=3;e++){U16(learn,e*0x104+2,10);U16(learn,e*0x104+6,20);}return source;
    }
    internal static void Run(Action<bool,string> check,Action<Action,string> reject)
    {
        var source=LowLevel();var personal=SwordShieldChecks.Table();var options=new SwordShieldGameplayOptions(123,Trainers:true){RandomizeTrainerSpecies=false,TrainerRules=new(){BetterMovesets=true}};
        var fallback=SwordShieldGameplay.Generate(source,personal,false,options);var output=fallback.Files()[Team];check(fallback.Warnings.Count==1&&BinaryPrimitives.ReadUInt16LittleEndian(output.AsSpan(18))==1&&BinaryPrimitives.ReadUInt16LittleEndian(output.AsSpan(10))==3,"Switch_Polish_LevelThreeWithZeroMinimumUsesFirstFutureAttackAndWarns");
        var banned=SwordShieldGameplay.Generate(source,personal,false,options with{TrainerRules=options.TrainerRules with{BannedMoves=new[]{1}}});check(BinaryPrimitives.ReadUInt16LittleEndian(banned.Files().GetValueOrDefault(Team,source[Team]).AsSpan(18))==2,"Switch_Polish_FallbackNeverBypassesBannedMoves");
        var strict=SwordShieldGameplay.Generate(source,personal,false,options with{TrainerRules=options.TrainerRules with{MinMovePower=255,StrongestAttackStat=true,AllowStatus=false}});check(strict.Warnings.Count>0&&BinaryPrimitives.ReadUInt16LittleEndian(strict.Files()[Team].AsSpan(18))==1,"Switch_Polish_ImpossibleOptionalFiltersDoNotBlockRandomization");
        source["bin/pml/waza/waza0005.wazabin"]=SwitchParityChecks.Move(5,1,150);personal[176+0x28]|=1;var machines=SwordShieldGameplay.Generate(source,personal,false,options with{TrainerRules=options.TrainerRules with{IncludeMachines=true}});check(BinaryPrimitives.ReadUInt16LittleEndian(machines.Files()[Team].AsSpan(18))==5&&machines.Warnings.Count==0,"Switch_Polish_BetterMovesIncludesCompatibleTM");
        personal[176+0x28]&=254;var incompatible=SwordShieldGameplay.Generate(source,personal,false,options with{TrainerRules=options.TrainerRules with{IncludeMachines=true}});check(Enumerable.Range(0,4).All(i=>BinaryPrimitives.ReadUInt16LittleEndian(incompatible.Files()[Team].AsSpan(18+i*2))!=5),"Switch_Polish_MachinePoolExcludesIncompatibleMoves");
        source["bin/pml/waza/waza0014.wazabin"]=SwitchParityChecks.Move(14,1,150);personal[176+0x3C]|=1;var tr=SwordShieldGameplay.Generate(source,personal,false,options with{TrainerRules=options.TrainerRules with{IncludeMachines=true}});check(BinaryPrimitives.ReadUInt16LittleEndian(tr.Files()[Team].AsSpan(18))==14,"Switch_Polish_BetterMovesIncludesCompatibleTR");
        var modes=SwitchParityChecks.Inputs();U16(modes[Team],18,1);U16(modes[Team],20,0);string second=Team.Replace("001","002");modes[second]=(byte[])modes[Team].Clone();modes["bin/trainer/trainer_data/trainer_data_002.bin"]=(byte[])modes["bin/trainer/trainer_data/trainer_data_001.bin"].Clone();var per=new SwordShieldTrainerOptions{SmartItems=true,ItemModes=new[]{new SwordShieldTrainerItemMode(1,0),new(2,2)}};var items=SwordShieldGameplay.Generate(modes,personal,false,new(71,Trainers:true){RandomizeTrainerSpecies=false,TrainerRules=per}).Files();int normal=BinaryPrimitives.ReadUInt16LittleEndian(items[Team].AsSpan(16)),competitive=BinaryPrimitives.ReadUInt16LittleEndian(items[second].AsSpan(16));check(new[]{234,158,266,267,640,275}.Contains(normal)&&new[]{220,268,270,287}.Contains(competitive),"Switch_Polish_SmartItemQualityIsIndependentPerTrainer");
        reject(()=>SwordShieldBattlePolicy.Validate(options with{TrainerRules=per with{ItemModes=new[]{new SwordShieldTrainerItemMode(1,3)}}}),"Switch_Polish_RejectsInvalidItemQuality");var json=JsonSerializer.Serialize(per with{IncludeMachines=true});var round=JsonSerializer.Deserialize<SwordShieldTrainerOptions>(json)!;check(round.IncludeMachines&&round.ItemModes.SequenceEqual(per.ItemModes),"Switch_Polish_MachinesAndQualitySurviveRecipeSerialization");
        var evo=new byte[72];foreach(var pair in new[]{(0,5),(1,6),(2,7),(3,8)}){int at=pair.Item1*8;U16(evo,at,pair.Item2);U16(evo,at+2,221);U16(evo,at+4,2);evo[at+6]=255;evo[at+7]=10;}string path="bin/pml/evolution/evo_001.bin";var converted=SwordShieldDataEditor.Randomize(SwordShieldDataSection.Evolutions,new Dictionary<string,byte[]>{{path,evo}},personal,new(123,RemoveTradeEvolutions:true));var result=converted.Files()[path];check(Enumerable.Range(0,3).All(i=>BinaryPrimitives.ReadUInt16LittleEndian(result.AsSpan(i*8))==4&&BinaryPrimitives.ReadUInt16LittleEndian(result.AsSpan(i*8+2))==0&&result[i*8+7]==37),"Switch_Polish_AllThreeTradeMethodsBecomeLevelThirtySeven");check(result.AsSpan(24).SequenceEqual(evo.AsSpan(24))&&Enumerable.Range(0,3).All(i=>result.AsSpan(i*8+4,3).SequenceEqual(evo.AsSpan(i*8+4,3))),"Switch_Polish_TradeConversionPreservesDestinationsFormsAndOtherMethods");
    }
    private static string Fixture(string temp)
    {
        string root=SwordShieldChecks.Fixture(temp,"source");foreach(var p in SwitchParityChecks.Inputs()){string f=Path.Combine(root,"romfs",p.Key);Directory.CreateDirectory(Path.GetDirectoryName(f)!);File.WriteAllBytes(f,p.Value);}var evo=new byte[72];for(int i=0;i<3;i++){U16(evo,i*8,5+i);U16(evo,i*8+2,221);U16(evo,i*8+4,2);}string path=Path.Combine(root,"romfs/bin/pml/evolution/evo_001.bin");Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllBytes(path,evo);return root;
    }
    private static IEnumerable<T> Descendants<T>(DependencyObject root)where T:DependencyObject{foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>()){if(child is T t)yield return t;foreach(var nested in Descendants<T>(child))yield return nested;}}
    internal static void RunUi(Action<bool,string> check)
    {
        int formatted=0;var group=new SwitchHistoryGroup("Large",10000,i=>{formatted++;return "Change "+i;});var history=new SwitchHistoryView(new[]{group});check(history.VisibleLines.Count==200&&formatted==200,"Switch_Polish_HistoryFormatsOnlyCurrentPageOfTenThousand");history.SetPage(49);check(history.VisibleLines.Count==200&&history.VisibleLines.Last()=="Change 9999"&&formatted==400,"Switch_Polish_HistoryLastPageRetainsEveryRecord");using var export=new StringWriter();history.Export(export);check(export.ToString().Contains("Change 0"+Environment.NewLine)&&export.ToString().Contains("Change 9999")&&export.ToString().Split('\n').Count(l=>l.StartsWith("Change "))==10000,"Switch_Polish_HistoryExportIncludesAllPages");var empty=new SwitchHistoryView(Array.Empty<SwitchHistoryGroup>());empty.SetPage(-1);check(empty.VisibleLines.Count==0&&empty.Page==0,"Switch_Polish_EmptyHistoryHasValidPaging");
        string temp=Path.Combine(Path.GetTempPath(),"dr-polish-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try
        {
            string root=Fixture(temp);var project=SwordShieldProject.Open(root);var trainer=new SwordShieldRecordEditor(project,SwordShieldDataSection.TrainerTeams);var view=new RecordEditorView(trainer);check(view.OptionControls.ContainsKey("GlobalMoves.IncludeTMs")&&new[]{"Normal","Important","Boss"}.All(c=>view.OptionControls.ContainsKey("GlobalItems.Quality"+c)),"Switch_Polish_UIExposesMachinesAndThreeItemQualities");var values=EditorValues.Flatten(trainer.RandomOptions);values.Remove("GlobalItems.QualityNormal");values.Remove("GlobalItems.QualityImportant");values.Remove("GlobalItems.QualityBoss");values["GlobalItems.Quality"]=1;values.Remove("GlobalMoves.IncludeTMs");trainer.RestoreOptions(JsonSerializer.Serialize(new{Format="DefinitiveRandomizer.SwitchOptions",Version=1,Section="TrainerTeams",Options=values}));var restored=EditorValues.Flatten(trainer.RandomOptions);check(new[]{"Normal","Important","Boss"}.All(c=>restored["GlobalItems.Quality"+c]==1)&&restored["GlobalMoves.IncludeTMs"]==0,"Switch_Polish_OldQualityMigratesToEveryCategory");
            var warningPreview=project.PreviewGameplay(new SwordShieldGameplayOptions(9,Trainers:true){RandomizeTrainerSpecies=false,TrainerRules=new(){BetterMovesets=true,MinMovePower=255}});project.ApplyGameplay(warningPreview);check(project.GameplayHistory.Last().Warnings?.Count>0&&project.GlobalHistorySummary().Contains("Aviso ·"),"Switch_Polish_FallbackWarningsPersistAndAppearInGlobalHistory");
            var evo=new SwordShieldRecordEditor(project,SwordShieldDataSection.Evolutions);var evolutionView=new RecordEditorView(evo);var button=Descendants<System.Windows.Controls.Button>(evolutionView).Single(b=>b.Content?.ToString()=="Eliminar evoluciones por intercambio · nivel 37");button.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));check(project.DataHistory.Count==0&&((System.Windows.Controls.Button)evolutionView.FindName("ApplyButton")).IsEnabled,"Switch_Polish_TradeButtonPreviewsWithoutApplying");var proposal=evo.PreviewTradeRemoval();evo.Apply(proposal);check(project.DataHistory.Single().Options?.RemoveTradeEvolutions==true,"Switch_Polish_TradeActionIsRecordedInHistory");var target=SwordShieldProject.Open(root);target.ApplyGlobal(target.PreviewGlobal(project.CaptureGlobal()));check(target.ReadData(SwordShieldDataSection.Evolutions).Where(c=>c.Field=="Nivel").All(c=>c.Value==37),"Switch_Polish_TradeActionReplaysThroughGlobalTemplate");
            // Level Up view on Sword/Shield: longer lists saved whole, «Expandir cantidad» and the 3DS options, and both replayed by Global Template.
            {
                var learnProject=SwordShieldProject.Open(root);var learn=new ThreeDS.Progressive.Services.Switch.SwordShieldLevelUpSource(learnProject);var levelUpView=new LevelUpView(learn);
                check(learn.Entries.Count>0&&learn.MaxMoves==64&&learn.RandomMovePool.Count>0&&!Descendants<System.Windows.Controls.CheckBox>(levelUpView).Any(c=>Equals(c.Content,"Permitir MO / HM")),"Switch_Polish_LevelUpViewOpensWithGen8Limits");
                int entry=learn.Entries[0].Index;var rows=learn.Read(entry).ToList();int count=rows.Count;var pool=learn.RandomMovePool;
                rows.Add(new ThreeDS.Progressive.Services.LevelUpMoveEntry{Move=pool[0],Level=90});rows.Add(new ThreeDS.Progressive.Services.LevelUpMoveEntry{Move=pool[^1],Level=0});learn.Save(entry,rows);
                var saved=learn.Read(entry);check(saved.Count==count+2&&saved[0].Level==0&&saved[^1] is {Level:90}&&saved.Select(r=>r.Level).SequenceEqual(saved.Select(r=>r.Level).Order()),"Switch_Polish_LevelUpSavesLongerListsAndEvolutionMoves");
                bool tooLong=false;try{learn.Save(entry,Enumerable.Range(0,65).Select(i=>new ThreeDS.Progressive.Services.LevelUpMoveEntry{Move=pool[0],Level=1}).ToArray());}catch(InvalidDataException){tooLong=true;}
                check(tooLong&&learn.Read(entry).Count==count+2,"Switch_Polish_LevelUpRejectsMoreThan64Moves");
                var random=learn.PrepareRandomization(new(false,true,60,true,12,true,true,40,true));learn.ApplyRandomization(random);
                check(learn.Entries.All(e=>learn.Read(e.Index) is var l&&l.Count>=12&&l.Take(4).All(r=>r.Level==1)&&l.All(r=>r.Level<=40&&r.Move is not (49 or 82))),"Switch_Polish_LevelUpExpandStartFourSpreadAndNoFixedDamage");
                learn.Save(entry,saved);
                var template=learnProject.CaptureGlobal();string json=template.ToJsonString();
                var replayed=SwordShieldProject.Open(root);replayed.ApplyGlobal(replayed.PreviewGlobal(template));
                check(json.Contains("learnset.manual")&&json.Contains("LearnExpandTo")&&replayed.ReadLearnset(entry).SequenceEqual(learnProject.ReadLearnset(entry))
                    &&learn.Entries.Where(e=>e.Index!=entry).All(e=>replayed.ReadLearnset(e.Index).Count>=12),"Switch_Polish_LevelUpGlobalTemplateReplaysListsAndOptions");
            }
        }finally{Directory.Delete(temp,true);}
    }
    internal static void Probe(string root)
    {
        var project=SwordShieldProject.Open(root);var rows=project.ReadData(SwordShieldDataSection.Evolutions);var methods=rows.Where(c=>c.Field=="Método"&&c.Value is 5 or 6 or 7).ToArray();var preview=project.PreviewData(SwordShieldDataSection.Evolutions,null,new SwordShieldDataOptions(123,RemoveTradeEvolutions:true));project.ApplyData(preview);var after=project.ReadData(SwordShieldDataSection.Evolutions);if(after.Any(c=>c.Field=="Método"&&c.Value is 5 or 6 or 7)||methods.Any(m=>!after.Any(c=>c.Resource==m.Resource&&c.Slot==m.Slot&&c.Field=="Nivel"&&c.Value==37)))throw new Exception("Trade conversion mismatch.");Console.WriteLine("PASS Switch_Polish_RealAllTradeEvolutionRoutesConvertedInMemory: "+methods.Length+"; "+string.Join(", ",methods.GroupBy(m=>m.Value).Select(g=>g.Key+"="+g.Count())));
        var trainers=new SwordShieldRecordEditor(project,SwordShieldDataSection.TrainerTeams);var values=EditorValues.Flatten(trainers.RandomOptions);values["GlobalMoves.Better"]=1;values["GlobalMoves.IncludeTMs"]=1;values["GlobalMoves.StrongStat"]=1;values["GlobalMoves.Power"]=0;values["GlobalItems.Smart"]=1;values["GlobalItems.QualityNormal"]=0;values["GlobalItems.QualityImportant"]=1;values["GlobalItems.QualityBoss"]=2;var result=trainers.Preview(values,trainers.Entries.Select(e=>e.Id).ToArray());trainers.Apply(result);Console.WriteLine("PASS Switch_Polish_RealAllRandomizedTrainerMovesAndCategoryItems: "+result.Changes.Count+" changes; "+result.Parameters.GetValueOrDefault("WarningCount")+" warnings");var target=SwordShieldProject.Open(root);target.ApplyGlobal(target.PreviewGlobal(project.CaptureGlobal()));Console.WriteLine("PASS Switch_Polish_RealGlobalReplayWithMachinesQualityAndWarnings: "+target.GameplayHistory.Count+" operations");Console.WriteLine("Original read-only; memory only; no export, installation or gameplay.");
    }
